window.__SITE_EN={"Loom & Ewe — Sợi len nhuộm tay từ một thung lũng":"Loom & Ewe — Hand-dyed wool from a single valley","Chuyển đến nội dung chính":"Skip to main content","Kệ sợi len":"Yarn Wall","Từ lông cừu":"Fleece to Skein","Thiết kế mẫu":"Fair Isle Lab","Bộ kit":"Kits","Lớp học":"Workshops","Giỏ len":"Basket","món":"items","Thiết kế họa tiết":"Chart a Pattern","Giỏ len của bạn":"Your Yarn Basket","Tạm tính":"Subtotal","Thanh toán":"Checkout","Sợi len nhuộm thủ công từ một thung lũng":"Hand-dyed wool from a single valley","Đan nên điều":"Knit something","bền bỉ qua":"that outlasts","mùa":"the","đông lạnh.":"winter.","Sợi len của chúng tôi đến từ đàn 140 con cừu cái tại nông trang Hollins, được kéo sợi ở xưởng bên kia đồi và nhuộm trong mười hai nồi màu ngay sau tiệm. Phần còn lại là tác phẩm từ đôi tay bạn.":"Our wool comes from a flock of 140 breeding ewes at Hollins Farm, spun across the hill, and hand-dyed in twelve enamel pots behind the shop. The rest is made with your hands.","Tự vẽ bảng họa tiết đan":"Chart a Fair Isle pattern","Khám phá kệ sợi len":"Explore the yarn wall","cừu cái, chung một đàn":"breeding ewes, one single flock","tông màu mùa này":"hand-dyed colorways this season","miễn phí vận chuyển từ":"free shipping threshold","“Dương Xỉ”":"“Bracken”","Mẻ nhuộm 0412":"Dye lot 0412","Kệ tường sợi len":"The Yarn Wall","Mười sắc màu,":"Ten colorways,","một triền đồi":"one hillside","Mỗi tông màu đều được đặt tên theo cảnh vật nhìn thấy từ cổng nông trang. Chọn một cuộn len trên kệ, chọn cỡ sợi bạn quen đan, và chúng tôi sẽ quấn mới ngay từ mẻ nhuộm trong tuần.":"Every shade is named for something seen from the Hollins farm gate. Pick a color from the wall, choose your weight, and we will cake it fresh from this week's dye lot.","chọn cỡ sợi nào?":"which weight do you need?","Lace (Mảnh)":"Lace","Kim 3 mm · khăn choàng, chập đôi tạo độ xù nhẹ":"3 mm needles · shawls, held double for halo","DK (Vừa)":"DK","Kim 4 mm · đan phối màu, tất chân, đồ em bé":"4 mm needles · colorwork, socks, baby knits","Aran (Dày)":"Aran","Kim 5 mm · họa tiết vặn thừng, áo len đan nhanh":"5 mm needles · cables, quick cozy sweaters","Chunky (Đại)":"Chunky","Kim 7 mm · hoàn thành chiếc mũ ấm chỉ trong một tối":"7 mm needles · finished beanie in an evening","Thêm vào giỏ ·":"Add to basket ·","Từ bộ lông đến cuộn sợi":"Fleece to Skein","Bảy tháng,":"Seven months,","ba dặm đường":"three miles","Tháng Năm":"May","Xén lông tại nông trang Hollins":"Shearing at Hollins Farm","Đàn cừu Cheviot và Shetland của Ruth Ashby được xén lông vào tuần nắng ráo đầu tiên của tháng Năm. Chúng tôi thu mua trọn đợt xén, cả lớp lông tơ mềm lẫn phần lông bảo vệ.":"Ruth Ashby's Cheviot and Shetland flock is shorn during the first dry week of May. We take the entire clip, soft underfleece and weather-hardy guard hair alike.","Tháng Bảy":"July","Giặt sạch và kéo sợi":"Scoured & spun at Beckside","Lông cừu vượt đồi sang xưởng Beckside để giặt sạch, chải thô và kéo thành dòng sợi tơ xốp nhẹ, bung nở mềm mại sau lần giặt đầu tiên.":"The fleeces travel over the ridge to Beckside Mill to be washed in brook water, carded, and woolen-spun into a springy, airy single that blooms after blocking.","Tháng Chín":"September","Nhuộm tay trong mười hai nồi":"Hand-dyed in twelve pots","Jess tự tay nhuộm từng mẻ phía sau cửa tiệm, kết hợp thảo mộc ven đường cùng phẩm màu dịu nhẹ. Không có hai mẻ nhuộm nào giống hệt nhau — và đó chính là nét quý giá.":"Jess dyes in small batches behind the shop using foraged hedgerow botanicals and low-impact dyes. No two pots take color identically — that is the point.","Tháng Mười Một":"November","Xoắn con len và gắn thẻ":"Skeined & labeled","Mỗi con len được xoắn gọn, gắn thẻ ghi rõ mã mẻ nhuộm cùng tên cánh đồng nơi đàn cừu gặm cỏ, rồi xếp lên kệ đúng dịp đợt gió lạnh đầu mùa.":"Every skein is twisted, tied, and stamped with the dye lot and the name of the pasture where the ewes grazed, ready for the first frost.","Xưởng phối màu họa tiết":"Fair Isle Color Lab","Vẽ sơ đồ mũi,":"Chart your grid,","xem mẫu đan thật":"watch it knit live","Chấm từng mũi trên bảng sơ đồ và mảnh vải mẫu sẽ tự đan ngay bằng chính sợi len của tiệm. Chọn sản phẩm bạn muốn đan, hệ thống sẽ tính chính xác số cuộn từng màu và tổng chi phí bộ kit (đã tính dư sợi vắt ngang mặt trái).":"Click each stitch on the grid and watch the knitted swatch render live using our actual yarn colors. Pick a project to calculate exact skeins per shade and total kit price (floats included).","Các màu len đang dùng":"Active palette","Đổi sang tông màu":"Swap to colorway","Công cụ":"Tools","Vẽ mũi":"Pencil","Tô cả hàng":"Row Fill","Đối xứng":"Mirror","Xóa trắng":"Clear Grid","Mẫu gợi ý":"Presets","Rừng thông":"Pine Forest","Ngôi sao":"Eight-point Star","Trái tim":"Folk Heart","Sóng nước":"Wave & Ripple","Bảng sơ đồ":"Stitch Chart","24 × 16 mũi đan":"24 × 16 stitches","di chuyển ·":"navigate ·","tô ·":"paint ·","màu len ·":"palette ·","đối xứng":"mirror","Mẫu đan thử":"Rendered Swatch","1,5 chu kỳ họa tiết trên mặt len":"1.5 pattern repeats in stocking stitch","cuộn len + bản in hướng dẫn":"skeins + printed pattern chart","Thêm bộ kit này":"Add custom kit","Định lượng sợi ước tính cho cỡ trung bình với dòng len Hollins DK, đã bao gồm phần sợi vắt ngang Fair Isle.":"Yarn requirements estimated for medium sizing in Hollins DK, including standard stranded Fair Isle floats.","Bộ kit đan sẵn":"Curated Knitting Kits","Trọn vẹn trong":"Everything in","một gói quà":"one brown parcel","Sợi len chuẩn định lượng, bản in công thức đan, khoen đánh dấu mũi và tấm thiệp viết tay. Tất cả được gói trong giấy kraft nâu và buộc bằng chính sợi len của mẻ nhuộm đó.":"Pre-measured yarn, printed pattern booklet, wooden stitch markers, and a handwritten card. Packed in brown kraft paper tied with waste thrums.","Lớp học & tối thứ Năm":"Workshops & Thursday Nights","Kéo ghế ngồi":"Pull up a chair","cùng đan len":"and knit with us","Căn phòng phía sau tiệm có 12 chỗ ngồi, ấm trà luôn nóng và chẳng ai phiền lòng nếu bạn lỡ tuột một mũi đan. Hãy mang theo món đồ đang đan dở hoặc bắt đầu một dự án mới cùng chúng tôi.":"The back room seats twelve, the kettle is always boiling, and nobody cares if you drop a stitch. Bring your current WIP or cast on something fresh with us.","Thư Chủ Nhật":"The Sunday Letter","Mẻ nhuộm mới,":"Fresh dye pots,","ưu tiên xem trước":"early access","Một bức thư mỗi sáng Chủ nhật: những sắc màu vừa ra lò từ nồi nhuộm, một mẫu công thức miễn phí hàng tháng và lịch mở lớp trước khi kín chỗ.":"One dispatch every Sunday morning: fresh shades straight from the dye pots, a free monthly stitch pattern, and workshop dates before they sell out.","Địa chỉ email":"Email address","Gửi Thư Chủ Nhật cho tôi":"Send me the Sunday Letter","Tiệm sợi len & xưởng nhuộm thủ công, mở cửa Thứ Ba đến Thứ Bảy.":"Hand-dyed yarn shop & craft dye studio, open Tuesday through Saturday.","Cửa hàng":"Shop","Bộ kit đan":"Knitting Kits","Ghé thăm":"Visit Us","Đêm đan len":"Knit Nights","Đàn cừu của tiệm":"Our Flock","Hỗ trợ":"Care Guide","Bản tin Chủ nhật":"Sunday Letter","Bảng cỡ sợi":"Yarn Weights","Vận chuyển":"Shipping & Returns","Thiết kế concept — thương hiệu giả định.":"Concept design — fictional brand.","Loom & Ewe cung cấp sợi len nhuộm thủ công từ một đàn cừu duy nhất, bộ kit đan len và các lớp học cuối tuần. Tự vẽ bảng họa tiết phối màu và xem ngay mẫu đan thực tế kèm lượng sợi và giá bộ kit.":"Loom & Ewe offers hand-dyed yarn from a single flock, curated knitting kits, and weekend workshops. Chart Fair Isle colorwork patterns and view live knitted swatches with yarn calculations.","Loom and Ewe, trang chủ":"Loom & Ewe, home","Chính":"Main","Mở menu":"Open menu","Đóng giỏ len":"Close basket","Các tông màu":"Colorways","Cỡ sợi len":"Yarn weight","Số lượng":"Quantity","Giảm một cuộn":"Decrease skeins","Thêm một cuộn":"Increase skeins","Bảng sơ đồ phối màu, 24 mũi nhân 16 hàng. Dùng phím mũi tên để di chuyển, phím Cách để tô màu, phím 1 đến 5 để chọn cuộn len.":"Colorwork chart, 24 stitches by 16 rows. Arrow keys to navigate, Spacebar to paint, keys 1 through 5 to pick yarn shade.","Dự án đan":"Knitting project","Dương Xỉ (Bracken)":"Bracken","Sắc nâu gỉ của dương xỉ khô trên đồi tháng Mười, nhuộm từ rễ cây thiên thảo và một chút khoáng sắt.":"The russet copper of withered October hill fronds, dyed with madder root and a trace of iron mordant.","Kim Tước (Gorse)":"Gorse","Hoa kim tước vàng rực thoảng hương dừa ven lối nhỏ. Nhuộm từ cỏ hoàng mộc và vỏ hành tây, bừng sáng những ngày âm u.":"Bright coconut-scented yellow blooms along the hedgerow. Dyed with weld and yellow onion skins, sunny on gray days.","Địa Y (Lichen)":"Lichen","Sắc xanh xám dịu dàng bám trên tường đá cổ. Tông màu được chọn đan nhiều nhất vì dễ phối với mọi sắc độ.":"Soft sage-gray clinging to drystone walls. Our most reached-for neutral that harmonizes with every shade.","Rêu Phong (Moss)":"Moss","Thảm rêu ướt đẫm dưới tán rừng dẻ gai. Nhuộm chồng hai lớp để tạo chiều sâu.":"Deep saturated olive from damp woodland hollows. Over-dyed in two stages for tonal depth.","Hồ Sâu (Loch)":"Loch","Mặt hồ Hollins lúc bốn giờ chiều tháng Mười Một, sắc lam chuyển dần sang xám khói rồi chạm bóng đêm.":"Hollins tarn at four on a November afternoon, deep slate blue fading through peat smoke to dusk.","Thạch Nam (Heather)":"Heather","Đồi hoa thạch nam tháng Tám trên cánh đồng cao, sắc tím bụi phớt ánh hồng ấm áp.":"High moorland heather in late August, a dusty lilac blush with warm rosy undertones.","Mận Gai (Sloe)":"Sloe","Trái mận gai chín sẫm sau đợt sương giá đầu tiên. Sắc tím rượu vang trầm mặc đầy cuốn hút.":"Deep inky purple after the first hard frost. A moody, brooding elderberry wine.","Thanh Lương (Rowan)":"Rowan","Chùm quả thanh lương trà đỏ thắm bên cổng rào. Sắc đỏ rực rỡ nhất cho đôi găng tay nổi bật giữa ngày tuyết.":"Scarlet berries hanging heavy beside the sheep pens. Our clearest red, knit for snowy mitts.","Than Bùn (Peat)":"Peat","Lông cừu Shetland nâu sẫm nguyên bản không nhuộm — sắc màu tự nhiên từ chính đàn cừu.":"Rich undyed moorit from our darkest Shetland hoggs — completely natural color straight from the sheep.","Yến Mạch (Oat)":"Oat","Lông cừu Cheviot kem ấm nguyên bản. Phông nền hoàn hảo cho hầu hết mọi bảng họa tiết phối màu.":"Warm undyed Cheviot cream. The natural background canvas for almost every Fair Isle chart.","Len cừu Cheviot & Shetland":"Cheviot & Shetland wool","Mohair non & tơ tằm":"Kid mohair & mulberry silk","Len cừu Corriedale":"Corriedale wool","Mũi {0}, hàng {1}: {2}":"Stitch {0}, row {1}: {2}","Đã tô màu {0}":"Painted color {0}","Sợi số {0}: {1}":"Yarn #{0}: {1}","Mũ len":"Beanie hat","Khăn ống":"Cowl","Găng tay":"Mittens","Áo len cổ tròn":"Yoke sweater","{0} cuộn":"{0} skeins","Bộ kit {0}, {1} cuộn len":"{0} kit, {1} skeins","{0} cuộn Hollins DK + bản in sơ đồ đan":"{0} skeins Hollins DK + printed pattern chart","tông màu nhuộm":"colorways","Chưa có cuộn len nào trên kim đan.":"No yarn cakes in your basket yet.","Bộ kit phối màu tự chọn":"Custom colorwork kit","Đây là cửa hàng thiết kế concept nên không thu phí. Giỏ len của bạn vẫn được lưu tại đây.":"This is a concept showcase, so no real payments are taken. Your basket remains saved.","Áo Len Ember Yoke":"Ember Yoke Sweater","Đan thành thạo":"Intermediate","Áo len cổ tròn đan liền với dải rừng thông và nền trời màu dương xỉ ấm. Đủ cỡ vòng ngực từ 80 đến 140 cm.":"Seamless circular yoke sweater featuring stylized firs across a warm bracken sky. Bust sizes 80 to 140 cm.","bán chạy":"popular","Mũ Len Hollins":"Hollins Beanie","Nhập môn phối màu":"Beginner colorwork","Hai màu sợi, họa tiết ngôi sao tám cánh đan vòng tròn. Đan gọn trong dịp cuối tuần để đội suốt mùa đông.":"Two-color stranded star pattern in the round. Cast on Friday evening, wear it by Sunday night.","Găng Tay Mận Gai":"Sloe Hedgerow Mitts","Trình độ trung cấp":"Adventurous beginner","Họa tiết trái tim trên mu bàn tay, chấm nhỏ lòng bàn tay cùng phần ngón cái ôm vừa vặn.":"Folk heart motif across the knuckles with dotted palm texture and gusseted thumbs for comfort.","Thêm bộ kit":"Add kit","Đã thêm ✓":"Added ✓","Đêm đan len Thứ Năm":"Thursday Knit Night","Miễn phí hàng tuần. Mang theo món đồ đang đan, kéo ghế ngồi trò chuyện và thưởng thức trà bánh tại tiệm.":"Free drop-in every week. Bring whatever is on your needles, take a stool, and help yourself to shortbread.","Miễn phí":"Free","Nhập môn đan phối màu":"Introduction to Colorwork","Cách cầm hai sợi len, giấu sợi vắt mặt trái và hoàn thiện chóp mũ Hollins trước 4 giờ chiều.":"Two-handed yarn dominance, trapping floats cleanly, and crowning your Hollins beanie before 4:00 PM.","£45 kèm len":"£45 incl. yarn","Trạm khâu vá đồ len":"Visible Mending Clinic","Mang chiếc áo len bị sờn rách của bạn tới đây. Học mũi thêu Swiss darning và vá trang trí nghệ thuật.":"Bring moth-bitten knitwear. Learn Swiss darning, duplicate stitch patches, and decorative sashiko joins.","Kỹ thuật Steeking nâng cao":"Masterclass: Steeking Without Fear","Cắt mở mặt len đan vòng tròn thành áo khoác cardigan. Chúng tôi hướng dẫn gia cố mép móc, bạn tự tay cầm kéo.":"Cut open a circular tube of knitting into a cardigan. We coach the crochet reinforcement, you wield scissors.","Còn":"Remaining","/ {0} chỗ · {1}":"/ {0} spots · {1}","Giữ chỗ cho tôi":"Book my place","Đã giữ chỗ ✓":"Spot booked ✓","Quấn mới từ mẻ nhuộm trong tuần":"Caked fresh from this week's dye lot","Miễn phí vận chuyển cho đơn từ £40":"Free UK shipping on orders over £40","Đêm đan len vào mỗi tối Thứ Năm":"Free knit night every Thursday evening","Một đàn cừu, một thung lũng":"Single-flock trace from Hollins Farm","Kéo sợi cách tiệm chỉ ba dặm":"Spun three miles away at Beckside Mill","tuyệt vời — hẹn gặp bạn sáng Chủ nhật, ấm trà đã sẵn sàng.":"lovely — see you Sunday morning, the kettle is on.","địa chỉ email này bị tuột một mũi rồi, bạn kiểm tra lại nhé?":"this email dropped a stitch; please check again?","lông cừu thô":"raw fleeces","xưởng sợi Beckside":"Beckside Mill","mười hai nồi nhuộm":"twelve dye pots","con len gắn thẻ":"labeled skeins","Đóng menu":"Close menu"};
